import java.util.ArrayList;
import java.util.List;

// 준비 값: 조회수를 1씩 올리는 작업의 수예요.
static final int TASKS = 2;

// 작업 하나가 거치는 단계예요. 준비된 단계 이름은 세 가지예요.
// "읽기": 공유 값을 자기 지역 값으로 읽어요. "쓰기": 지역 값 + 1을 공유 값에 써요.
// "읽고쓰기": 읽기와 쓰기를 다른 작업이 끼어들 수 없는 한 단계로 해요.
static List<String> steps() {
    // 고칠 곳: 지금은 읽기와 쓰기가 따로라서 그 사이에 다른 작업이 끼어들 수 있어요.
    return List.of("읽기", "쓰기");
}

static int schedules = 0, lost = 0;

// 준비 코드: 각 작업의 단계 순서는 지키면서, 작업끼리 끼어드는 모든 순서를 하나씩 만들어요.
static void explore(int[] done, List<String> order) {
    int per = steps().size();
    boolean finished = true;
    for (int t = 0; t < TASKS; t++) {
        if (done[t] < per) {
            finished = false;
            done[t]++;
            order.add((char) ('A' + t) + " " + steps().get(done[t] - 1));
            explore(done, order);
            order.remove(order.size() - 1);
            done[t]--;
        }
    }
    if (finished) run(order);
}

// 준비 코드: 한 순서를 실제로 따라가며 공유 값과 각 작업의 지역 값을 기록해요.
static void run(List<String> order) {
    schedules++;
    int shared = 0;
    int[] local = new int[TASKS];
    for (String step : order) {
        int t = step.charAt(0) - 'A';
        switch (step.substring(2)) {
            case "읽기" -> local[t] = shared;
            case "쓰기" -> shared = local[t] + 1;
            case "읽고쓰기" -> shared = shared + 1;
            default -> throw new IllegalStateException("모르는 단계 " + step);
        }
    }
    boolean ok = shared == TASKS;
    if (!ok) lost++;
    System.out.println("순서 " + schedules + " | " + String.join(", ", order) + " | 결과 " + shared + (ok ? "" : " 갱신 잃음"));
}

void main() {
    explore(new int[TASKS], new ArrayList<>());
    System.out.println("가능한 순서 " + schedules + "개 중 " + lost + "개에서 갱신을 잃었어요.");
}

